<?php
namespace App\Services\HumanCapital\Payroll;
final class LegacyTerTaxEngine {
    public function calculate(string $taxStatus,float $taxable): array {
        $category=$this->category($taxStatus);
        $rate=$this->rateFor($category,max(0,$taxable));
        $amount=floor(max(0,$taxable)*$rate);
        return ['category'=>$category,'rate'=>$rate,'taxable'=>max(0,$taxable),'amount'=>$amount];
    }
    private function category(string $status): string {
        $status=strtoupper(trim($status));
        if($status==='K/3') return 'C';
        if(in_array($status,['TK/2','TK/3','K/1','K/2'],true)) return 'B';
        if($status==='' || in_array($status,['TK/0','TK/1','K/0'],true)) return 'A';
        return 'A';
    }
    private function rateFor(string $category,float $taxable): float {
        foreach($this->brackets($category) as [$max,$rate]) if($taxable<=$max) return $rate;
        return .34;
    }
    private function brackets(string $category): array {
        return match($category){
            'B'=>[[6200000,0],[6500000,.0025],[6850000,.005],[7300000,.0075],[9200000,.01],[10750000,.015],[11250000,.02],[11600000,.025],[12600000,.03],[13600000,.04],[14950000,.05],[16400000,.06],[18450000,.07],[21850000,.08],[26000000,.09],[27700000,.10],[29350000,.11],[31450000,.12],[33950000,.13],[37100000,.14],[41100000,.15],[45800000,.16],[49500000,.17],[53800000,.18],[58500000,.19],[64000000,.20],[71000000,.21],[80000000,.22],[93000000,.23],[109000000,.24],[129000000,.25],[163000000,.26],[211000000,.27],[374000000,.28],[459000000,.29],[555000000,.30],[704000000,.31],[957000000,.32],[1405000000,.33],[50000000000,.34]],
            'C'=>[[6600000,0],[6950000,.0025],[7350000,.005],[7800000,.0075],[8850000,.01],[9800000,.0125],[10950000,.015],[11200000,.0175],[12050000,.02],[12950000,.03],[14150000,.04],[15550000,.05],[17050000,.06],[19500000,.07],[22700000,.08],[26600000,.09],[28100000,.10],[30100000,.11],[32600000,.12],[35400000,.13],[38900000,.14],[43000000,.15],[47400000,.16],[51200000,.17],[55800000,.18],[60400000,.19],[66700000,.20],[74500000,.21],[83200000,.22],[95600000,.23],[110000000,.24],[134000000,.25],[169000000,.26],[221000000,.27],[390000000,.28],[463000000,.29],[561000000,.30],[709000000,.31],[965000000,.32],[1419000000,.33],[50000000000,.34]],
